            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
        return len(stack) == 0

    open_count_1 = lst[0].count('(')
    close_count_1 = lst[0].count(')')
    open_count_2 = lst[1].count('(')
    close_count_2 = lst[1].count(')')

    if open_count_1 != close_count_1 or open_count_2 != close_count_2:
        return 'No'

    concat_options = [lst[0] + lst[1], lst[1] + lst[0]]

    for concat in concat_options:
        if is_balanced(concat):
            return 'Yes'

    return 'No'

